"""Build original practice assessments and deterministic, offline listening audio.

Question answers are deliberately kept in this local learning application, not
hidden behind a claim of proctoring. The UI shuffles options for each attempt.
"""
import json, subprocess, base64, shutil
from pathlib import Path
ROOT=Path(__file__).parent
BANKS={}
def q(stem,correct,a,b,c,why,skill='conceptos',code='',passage='',listen=''):
    return dict(stem=stem,options=[correct,a,b,c],correct=0,why=why,skill=skill,code=code,passage=passage,listen=listen)
def bank(key,route,label,questions,task,criteria,reading=None,listening=None,seconds=0):
    assert len(questions)==10
    for i,item in enumerate(questions): item['id']=f'{key}-q{i+1}'
    BANKS[key]=dict(key=key,route=route,label=label,version=1,questions=questions,
       minis=[[x['id'] for x in questions[:3]],[x['id'] for x in (questions[7:10] if route=='ingles' else questions[3:6])]],
       reading=reading or {},listening=listening or {},practical=dict(task=task,criteria=criteria,minSeconds=seconds))
